<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,watch,nextTick} from 'vue'
import ImageEditor from './ImageEditor.vue'
import Portrait from './Portrait.vue'
import {personState,profile} from './people'
const props=defineProps<{project:Record<string,any>}>();const emit=defineEmits(['replace','running'])
const status=ref<any>({}),tasks=ref<any[]>([]),busy=ref(false),error=ref(''),message=ref(''),documentId=ref(''),page=ref(1),pages=ref('1'),target=ref('background'),selected=ref(''),zoom=ref(100)
const mode=ref('select'),deleted=ref<any>(null),names=ref<Record<string,string>>({}),duplicates=ref<Record<string,boolean>>({}),candidateReview=ref(false)
const kinds:Record<string,string>={background:'历史背景',relationships:'人物与关系',narrative:'已有历史叙事（选填）'}
const doc=computed(()=>props.project.documents?.find((d:any)=>d.id===documentId.value))
const people=computed(()=>props.project.annotations.filter((a:any)=>a.kind==='character'))
const narrativeMode=computed(()=>props.project.materialInputs.narrative.trim()?'保留已有历史叙事框架':'基于历史背景共创故事')
let timer:ReturnType<typeof setInterval>|undefined;let mounted=true;let polling=false
async function request(path:string,method='GET',body?:any){const r=await fetch('/api'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok){const err:any=Error(typeof v.detail==='string'?v.detail:v.detail?.message||JSON.stringify(v.detail));err.detail=v.detail;throw err;}return v}
async function save(){const p=await request('/projects/'+props.project.id,'PUT',props.project);emit('replace',p);return p}
async function poll(){if(polling)return;polling=true;try{const previous=tasks.value;const rows=await request(`/projects/${props.project.id}/tasks`);if(!mounted)return;tasks.value=rows;if(tasks.value.some(t=>t.applied&&previous.find(v=>v.id===t.id)&&!previous.find(v=>v.id===t.id)?.applied))emit('replace',await request('/projects/'+props.project.id));status.value=await request('/status')}catch(e){if(mounted)error.value=String(e)}finally{polling=false}}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function check(kind:string){await run(async()=>{const r=await request('/models/check','POST',{kind});message.value=r.ok?'连接成功':'未返回有效结果'})}
async function task(kind:string,extra?:any){await run(async()=>{const p=await save();const submitted=await request(`/projects/${p.id}/tasks`,'POST',{version:p.version,kind,documentId:documentId.value,pages:pages.value.split(',').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v)&&v>0),trigger:'user_button',...extra});tasks.value.unshift(submitted);await poll()})}
async function upload(e:Event,type:string){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{const p=await save();const form=new FormData();form.append('file',f);emit('replace',await request(`/projects/${p.id}/${type}?version=${p.version}`,'POST',form));await poll()})}
async function adopt(legacy=false,updateIds:string[]=[]){await run(async()=>{const p=await save();emit('replace',await request(`/projects/${p.id}/materials/adopt`,'POST',{version:p.version,legacy,updateIds}));message.value='已采用建议，原资料及稳定角色ID保留';candidateReview.value=false})}
function changed(id:string){const a=props.project.annotations.find((a:any)=>a.id===id);if(a){a.confirmed=false;a.identityConfirmed=false;a.needsReview=true}for(const o of props.project.observations.filter((o:any)=>o.annotationId===id)){o.confirmed=false;o.stale=true}for(const m of props.project.matches.filter((m:any)=>m.annotationId===id)){m.confirmed=false;m.stale=true}}
function observation(a:any){return props.project.observations.find((o:any)=>o.annotationId===a.id)}
function match(a:any){return props.project.matches.find((m:any)=>m.annotationId===a.id)}
function choose(a:any){const m=match(a);if(m){m.characterId=a.characterId;m.confirmed=false;m.manual=true;m.stale=false}a.identityConfirmed=false;a.needsReview=true}
async function confirm(a:any){await run(async()=>{const p=await save();emit('replace',await request(`/projects/${p.id}/people/${a.id}/confirm`,'POST',{version:p.version,characterId:a.characterId}));message.value='人物资料与姓名对应已确认并保存'})}
function character(a:any){return props.project.characters.find((c:any)=>c.id===a.characterId)}
function remove(){const id=selected.value;const index=props.project.annotations.findIndex((a:any)=>a.id===id);if(index<0)return;deleted.value=JSON.parse(JSON.stringify({annotation:props.project.annotations[index],index,observations:props.project.observations.filter((o:any)=>o.annotationId===id),matches:props.project.matches.filter((m:any)=>m.annotationId===id)}));props.project.annotations.splice(index,1);props.project.observations=props.project.observations.filter((o:any)=>o.annotationId!==id);props.project.matches=props.project.matches.filter((m:any)=>m.annotationId!==id);selected.value=''}
function undo(){if(!deleted.value)return;const d=deleted.value;props.project.annotations.splice(d.index,0,d.annotation);props.project.observations.push(...d.observations);props.project.matches.push(...d.matches);selected.value=d.annotation.id;deleted.value=null}
async function namePerson(a:any,useExisting=false){await run(async()=>{const p=await save();try{emit('replace',await request(`/projects/${p.id}/people/${a.id}/name`,'POST',{version:p.version,name:names.value[a.id]||'',useExisting}));duplicates.value[a.id]=false;names.value[a.id]=''}catch(e:any){if(e.detail?.code==='name_exists'){duplicates.value[a.id]=true;message.value=e.detail.message}else throw e}})}

function confirmObservation(a:any){const o=observation(a);if(o){o.confirmed=a.confirmed;o.description=a.description;o.stale=false}}
function editMaterial(){props.project.materialAnalysis.stale=true}
function insert(text:string){const old=props.project.materialInputs[target.value];props.project.materialInputs[target.value]=old+(old.trim()?'\n\n':'')+text;editMaterial();message.value='已放入选定输入框，尚未调用模型'}
async function select(id:string,fromCard=false){selected.value=id;if(!fromCard){await nextTick();document.getElementById('person-'+id)?.scrollIntoView({block:'nearest',behavior:'smooth'})}}
const running=computed(()=>busy.value||tasks.value.some(t=>['queued','running'].includes(t.status)))
watch(running,v=>emit('running',v),{immediate:true})
onMounted(()=>{poll();timer=setInterval(poll,2500)});onUnmounted(()=>{mounted=false;clearInterval(timer);emit('running',false)})
</script>
<template>
<div v-if="error" class="banner error" role="alert">{{error}}</div><div v-if="message" class="banner">{{message}}</div>
<article class="materials"><h2>资料输入</h2><div class="material-grid"><label v-for="(name,key) in kinds">{{name}}<textarea rows="9" v-model="project.materialInputs[key]" @input="editMaterial" :placeholder="key==='narrative'?'如果画作有史料记载的故事，请填入事件经过；没有可留空。':'整段粘贴资料，可将出处和链接一并写入。'"/></label></div><div class="actions"><button class="primary" :disabled="running" @click="task('materials')">整理资料并提取人物 · 调用 LLM</button><span class="mode">{{narrativeMode}}</span></div><small>填写已有叙事表示你提供了历史故事框架，不代表系统已经独立核实。留空时，新增故事事件属于共创内容。</small>
<div v-if="project.materialAnalysis.summary" class="card"><p>{{project.materialAnalysis.summary}}</p><small v-if="project.materialAnalysis.stale">资料已变化，旧整理结果待复核。点击按钮重新整理。</small><details><summary>查看整理结果与原文片段</summary><p v-for="event in project.materialAnalysis.eventFramework">{{event}}</p><p v-for="s in project.materialSegments"><b>{{kinds[s.kind]}}</b> · {{s.summary}}<small>原文位置 {{s.start}}–{{s.end}} · v{{s.sourceVersion}}</small><q>{{s.quote}}</q></p></details><button :disabled="running||project.materialAnalysis.stale" @click="candidateReview=!candidateReview">查看人物候选差异并采用</button><div v-if="candidateReview"><div v-for="c in project.materialAnalysis.characters" class="card"><b>{{c.name}}</b><p>{{profile(c)}}</p><template v-if="project.characters.some((v:any)=>v.name===c.name)"><small>现有：{{profile(project.characters.find((v:any)=>v.name===c.name))}}</small><button @click="adopt(false,[project.characters.find((v:any)=>v.name===c.name).id])">采用此人物更新（保留ID）</button></template><small v-else>新增候选人物</small></div><button @click="adopt()">只补充新增人物，保留已有资料</button></div></div>
<details v-if="project.sources.some((s:any)=>s.method!=='material_input')"><summary>旧资料与文件原文（保留引用）</summary><button :disabled="running" @click="task('legacy_materials')">整理旧资料到三段输入 · 调用 LLM</button><details v-for="s in project.sources.filter((s:any)=>s.method!=='material_input')" class="card"><summary>{{s.title}}</summary><p class="pre">{{s.text}}</p><small>{{s.citation}}</small></details></details>
<div v-if="project.legacyMaterialProposal" class="card"><h3>三段输入建议</h3><p v-for="(name,key) in kinds"><b>{{name}}</b><br>{{project.legacyMaterialProposal[key]}}</p><small>采用将替换当前三段输入；旧资料和旧引用仍然保留。</small><button @click="adopt(true)">采用这三段建议</button></div>
</article>
<article class="visual-workspace"><div class="actions"><h2>画作与人物</h2><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'image')"><button class="primary" :disabled="running||!project.image" @click="task('detect')">检测人物 · 本地模型</button><button :disabled="running||!people.length||!project.characters.length" @click="task('vision_match')">分析外观并建议身份匹配 · 调用 LLM</button></div><small>视觉匹配将分析全图、{{people.length}} 个人物裁切及身份候选，包含多次模型调用。修改框或姓名不调用模型。</small>
<div class="visual-grid"><div class="canvas-panel"><label>缩放 {{zoom}}%<input type="range" min="50" max="300" v-model.number="zoom"></label><ImageEditor v-if="project.image" :project="project" :zoom="zoom" :selected-id="selected" :disabled="running" :mode="mode" @added="mode='select'" @select="select($event)" @changed="changed"/><div v-else class="empty">上传画作图片开始</div><details v-if="project.visualOverview"><summary>全图观察与推测</summary><p>{{project.visualOverview.summary}}</p><p v-for="s in project.visualOverview.scenes">{{s.description}}<small>{{s.inference}}</small></p></details></div>
<div class="people-column"><div class="people-toolbar"><b>人物 · {{selected?'已选择 '+(people.findIndex((a:any)=>a.id===selected)+1):'未选择'}}</b><div class="actions"><button :class="{active:mode==='select'}" @click="mode='select'">选择／调整框</button><button :class="{active:mode==='add'}" @click="mode='add'">新增人物框</button><button :disabled="!selected" @click="remove">删除所选框</button><button :disabled="!deleted" @click="undo">撤销删除</button><button @click="mode='pan'">平移画作</button></div><small v-if="mode==='add'">在原图拖动绘制漏检人物框。</small></div><div class="person-list"><div v-if="!people.length" class="empty">点击“检测人物”，或在原图拖动补框。</div><section v-for="(a,i) in people" :id="'person-'+a.id" class="person-card" :class="[{chosen:selected===a.id},personState(project,a).key]" @click="select(a.id,true)"><div class="portrait"><span class="person-status" :class="personState(project,a).key">● {{personState(project,a).label}}</span><Portrait :url="project.image" :box="a"/><small>人物 {{Number(i)+1}}</small></div><div class="person-fields"><label>姓名<select v-model="a.characterId" @change="choose(a)"><option value="">未确定／资料未提及</option><option v-for="c in project.characters" :value="c.id">{{c.name}}</option></select></label><p class="profile">{{profile(character(a))}}</p><details v-if="character(a)"><summary>查看原文依据</summary><div v-for="m in character(a).mentions"><small>{{kinds[m.kind]||'原文'}} · 位置 {{m.start}}–{{m.end}} · v{{m.sourceVersion}}</small><q>{{m.quote}}</q></div><p v-if="!character(a).mentions?.length">{{character(a).evidence||'未提供原文定位；请核对资料。'}}</p></details><button :disabled="!a.characterId" @click.stop="confirm(a)">核对并确认此人物</button><small>确认已展示的人物资料与画面姓名对应。</small><details><summary>直接命名／资料未覆盖的人物</summary><input v-model="names[a.id]" placeholder="输入姓名或角色称谓"><button :disabled="!names[a.id]?.trim()" @click.stop="namePerson(a)">创建并关联</button><div v-if="duplicates[a.id]"><small>已有同名角色。</small><button @click.stop="namePerson(a,true)">关联已有角色</button></div></details><label>可见特征<textarea v-model="a.description" @input="a.confirmed=false;confirmObservation(a)"/></label><label><input type="checkbox" v-model="a.confirmed" @change="confirmObservation(a)">确认画面观察</label><details v-if="observation(a)?.inference"><summary>视觉推测（非历史依据）</summary><p>{{observation(a).inference}}</p></details><details v-if="match(a)"><summary>匹配理由与不确定性</summary><p>{{match(a).reason}}</p></details></div></section></div></div></div></article>
<details class="document-tools"><summary>从文件辅助填入资料／扫描页 OCR</summary><article><input type="file" accept=".txt,.md,.pdf,.png,.jpg,.jpeg,.webp" @change="upload($event,'documents')"><select v-model="documentId" @change="page=1"><option value="">选择已导入文件</option><option v-for="d in project.documents" :value="d.id">{{d.title}}（{{d.pageCount}}页）</option></select><template v-if="doc"><label>预览页码<input type="number" min="1" :max="doc.pageCount" v-model="page"></label><div class="document-grid"><div><iframe v-if="doc.format==='text'" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/1`" title="原文"/><img v-else class="page-preview" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/${page}`"></div><div><label>放入哪个输入框<select v-model="target"><option v-for="(name,key) in kinds" :value="key">{{name}}</option></select></label><div v-for="s in project.sources.filter((s:any)=>s.documentId===doc.id&&s.page===Number(page))"><textarea rows="10" v-model="s.text"/><button @click="insert(s.text)">将此页文本放入选定输入框</button></div><template v-if="doc.format!=='text'"><label>识别页码（逗号分隔，最多20页）<input v-model="pages"></label><small>将执行最多 {{pages.split(',').filter(v=>v.trim()).length}} 次视觉调用，需校对原页。</small><button :disabled="running" @click="task('ocr')">OCR 识别所选页 · 调用 LLM</button></template></div></div></template></article></details>
<div v-for="t in tasks.slice(0,4)" class="task-row"><b>{{({materials:'资料整理',legacy_materials:'旧资料整理',vision_match:'外观与身份分析',detect:'人物检测',ocr:'文字识别'} as Record<string,string>)[t.kind]||t.kind}}</b> · {{t.progress}}<button v-if="['failed','stale','interrupted'].includes(t.status)" :disabled="running" @click="task(t.kind,{documentId:t.request.documentId,pages:t.request.pages})">重试 · {{t.kind==='detect'?'本地模型':'调用 LLM'}}</button></div>
<details class="settings"><summary>模型设置与连通性测试</summary><small>文本 {{status.textModel}} · 视觉 {{status.visionModel}} · 检测器 {{status.detectorLoaded?'已加载':status.detectorCached?'已缓存':'未加载'}}。测试按钮会发送真实请求。</small><div class="actions"><button @click="check('text')">测试文本模型 · 调用 API</button><button @click="check('vision')">测试视觉模型 · 调用 API</button></div></details>
</template>
<style scoped>.materials,.visual-workspace{margin-bottom:24px}.material-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.mode{font-size:13px;color:#31594b}.visual-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,1fr);gap:24px;margin-top:20px}.canvas-panel{position:sticky;top:15px;align-self:start}.person-list{max-height:750px;overflow:auto;padding:2px 8px}.person-card{display:grid;grid-template-columns:110px 1fr;gap:14px;padding:14px;border:1px solid #d8dfd0;border-radius:8px;margin:0 0 12px;background:#fafaf4}.person-card.confirmed{border-color:#238052;background:#edf7ef}.person-card.pending,.person-card.review{border-color:#bd8c35;background:#fff9ed}.person-card.unnamed{border-color:#a7afaa;background:#f1f3f0}.person-card.chosen{outline:3px solid #406ec0;outline-offset:-3px}.person-status{display:block;font-size:12px;border-radius:5px;padding:5px;margin-bottom:9px;background:#eee}.person-status.confirmed{color:#1f7148;background:#d6efdf}.person-status.pending,.person-status.review{color:#8c600e;background:#f8e8bb}.person-status.unnamed{color:#68716c;background:#e0e5e0}.people-toolbar{position:sticky;top:0;background:#fffef9;padding:12px;border-bottom:1px solid #ccd7c6;z-index:2}.people-toolbar button{font-size:12px;padding:7px}.people-toolbar .active{background:#31594b;color:white}.profile{font-size:13px}.person-list{max-height:650px}.person-fields label{margin:4px 0}.person-fields textarea{min-height:65px}.portrait{padding-top:12px;text-align:center}.document-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.page-preview{max-width:100%;max-height:550px;object-fit:contain}iframe{width:100%;height:400px}.document-tools,.settings{margin:20px 0;padding:16px;border:1px solid #d9dfd0;border-radius:8px}.task-row{font-size:13px;padding:12px;background:#e9eee2;margin:6px 0;border-radius:5px}summary{cursor:pointer}@media(max-width:900px){.material-grid{grid-template-columns:1fr}.document-grid{grid-template-columns:1fr}}@media(max-width:700px){.visual-grid{grid-template-columns:1fr}.canvas-panel{position:static}}
</style>
